              "url": "https://perso.univ-rennes1.fr/bachir.bekka/KazhdanTotal.pdf",
              "locator": "Appendix F, §§F.1-F.2: Corollary F.1.5, Theorem F.2.2, Lemma F.2.8, Corollary F.2.9"
            }
